SVC_B64 = ''
ROUTER_B64 = ''
import os, sys, base64, py_compile

ROOT = os.environ.get("ROOT", "/home/ubuntu/testlogon")
TS = os.environ.get("TS", "0")
APPLY_TABLE = os.environ.get("APPLY_TABLE", "0") == "1"


def write_new(path, b64):
    full = os.path.join(ROOT, path)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    open(full, "wb").write(base64.b64decode(b64))
    py_compile.compile(full, doraise=True)
    print("WROTE", path)


def patch(path, marker, edits):
    full = os.path.join(ROOT, path)
    s = open(full).read()
    if marker in s:
        print("SKIP", path, "(marker present)")
        return
    bak = full + f".bak_ecomd4_{TS}"
    if not os.path.exists(bak):
        open(bak, "w").write(s)
    for old, new in edits:
        c = s.count(old)
        assert c == 1, f"{path}: anchor count {c} for {old[:60]!r}"
        s = s.replace(old, new, 1)
    open(full, "w").write(s)
    try:
        py_compile.compile(full, doraise=True)
    except Exception:
        open(full, "w").write(open(bak).read())
        raise
    print("PATCHED", path, "(bak", os.path.basename(bak) + ")")


def ensure_table():
    from app.core.tables import ddb
    from app.core.settings import S as _S
    name = _S.shipment_tracking_table_name
    client = ddb.meta.client
    try:
        client.create_table(
            TableName=name, BillingMode="PAY_PER_REQUEST",
            AttributeDefinitions=[
                {"AttributeName": "ship_group_id", "AttributeType": "S"},
                {"AttributeName": "tracking_number_norm", "AttributeType": "S"},
            ],
            KeySchema=[{"AttributeName": "ship_group_id", "KeyType": "HASH"}],
            GlobalSecondaryIndexes=[{
                "IndexName": "GSI_TRACKING",
                "KeySchema": [{"AttributeName": "tracking_number_norm", "KeyType": "HASH"}],
                "Projection": {"ProjectionType": "ALL"},
            }],
        )
        client.get_waiter("table_exists").wait(TableName=name)
        print("TABLE_CREATED", name)
    except Exception as e:
        if e.__class__.__name__ == "ResourceInUseException" or "ResourceInUse" in str(e) or "preexist" in str(e).lower():
            print("TABLE_EXISTS", name)
        else:
            raise


